import React from 'react';
import { C } from '../data';
import FadeIn from './FadeIn';

export default function SectionHeader({ tag, title, subtitle }) {
  return (
    <FadeIn className="text-center mb-16">
      {/* Tag: Thoda zyada space aur refined border ke saath */}
      <div
        className="inline-block px-5 py-1.5 rounded-full text-[10px] font-extrabold uppercase tracking-[0.2em] mb-6"
        style={{ 
          background: 'rgba(245,166,35,0.08)', // Very subtle gold tint
          color: C.gold,
          border: `1px solid rgba(245,166,35,0.2)`
        }}
      >
        {tag}
      </div>

      {/* Main Title: Playfair Display for academic feel */}
      <h2
        className="text-4xl md:text-5xl font-bold mb-6"
        style={{ 
          color: '#111827', // Deep Charcoal/Black for white theme
          fontFamily: "'Playfair Display', Georgia, serif",
          lineHeight: 1.2
        }}
      >
        {title}
      </h2>

      {/* Subtitle: Clean and readable spacing */}
      {subtitle && (
        <p 
          className="text-lg max-w-2xl mx-auto leading-relaxed" 
          style={{ 
            color: '#6b7280', // Soft Muted Gray
            fontWeight: 400
          }}
        >
          {subtitle}
        </p>
      )}

      {/* Subtle Divider Line below subtitle for professional touch */}
      <div 
        style={{ 
          width: '60px', 
          height: '3px', 
          background: C.gold, 
          margin: '32px auto 0',
          borderRadius: '2px'
        }} 
      />
    </FadeIn>
  );
}
